const esc = (s) => s.replace(/`/g, "\\`");
const html = `<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexSpace 租客員工</title><style>
*{box-sizing:border-box}body{margin:0;background:#eae7e2;font-family:Arial,'Microsoft JhengHei',sans-serif;color:#16120e}.app{width:390px;min-height:100vh;margin:auto;background:#fafaf9;padding-bottom:75px}header{height:58px;background:#fff;border-bottom:1px solid #eae7e2;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font-weight:bold}main{padding:16px}.hero{padding:25px 20px 30px;background:linear-gradient(135deg,#f79431,#ad5e10);color:#fff;border-radius:0 0 24px 24px}.hero h1{margin:42px 0 5px;font-size:27px}.hero p{margin:0;color:#fff5e9;font-size:14px}h2{font-size:18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.grid button,.list button{background:#fff;border:1px solid #eae7e2;border-radius:13px;padding:13px;text-align:center;min-height:86px;box-shadow:0 2px 8px #0000000b}.grid span{display:block;color:#f79431;font-size:25px;margin-bottom:8px}.list button{display:block;width:100%;min-height:51px;text-align:left;margin:7px 0;padding:13px}.card{background:#fff;border:1px solid #eae7e2;border-radius:13px;padding:14px;margin:10px 0}.card h3{font-size:15px;margin:2px 0 6px}.card p{font-size:12px;color:#655e55;margin:0}.pill{float:right;background:#fef0dc;color:#ad5e10;border-radius:99px;padding:5px 8px;font-size:11px}.actions{display:flex;gap:8px;margin-top:12px}.primary,.secondary,.danger{border:0;border-radius:10px;min-height:43px;padding:0 15px;font-weight:bold}.primary{background:#f79431;color:#fff}.secondary{background:#fff;color:#d67820;border:1px solid #f79431}.danger{background:#c7372f;color:#fff}.cta{width:100%;margin:10px 0}.tabs{display:flex;gap:25px;border-bottom:1px solid #eae7e2;margin-bottom:10px}.tabs button{padding:10px 2px;border:0;background:none;color:#655e55}.tabs .on{color:#f79431;border-bottom:2px solid #f79431}.balance{background:#fff8f0;border:1px solid #fddab0;padding:13px;border-radius:12px;font-size:13px}.balance b{float:right;color:#ad5e10;font-size:21px}.form label{display:block;margin:14px 0;font-size:13px;font-weight:bold}.form input,.form select,.form textarea{width:100%;min-height:43px;border:1px solid #eae7e2;border-radius:9px;background:#fff;padding:10px;margin-top:6px;font:inherit}.form textarea{height:78px}.hide{display:none}nav{position:fixed;bottom:0;width:390px;height:70px;background:#fff;border-top:1px solid #eae7e2;display:flex;justify-content:space-around}nav button{border:0;background:none;color:#655e55;font-size:11px}nav button.on{color:#f79431;font-weight:bold}.toast{position:fixed;bottom:85px;width:340px;margin-left:25px;background:#2b2520;color:white;border-radius:10px;padding:13px;text-align:center;font-size:13px}.qr{font-family:monospace;font-size:70px;line-height:.72;letter-spacing:-13px;background:#fff;width:205px;height:205px;margin:25px auto;display:grid;place-content:center;overflow:hidden}.center{text-align:center;padding-top:35px}.modal{position:fixed;inset:0;background:#16120e88;display:grid;place-items:center;padding:30px}.modal>div{background:#fff;border-radius:16px;padding:22px;text-align:center;width:330px}.muted{color:#655e55;font-size:13px}.filter button{margin-right:8px}.upload{border:1px dashed #f79431;color:#d67820;padding:17px;text-align:center;border-radius:10px;font-size:13px}
</style></head><body><div class="app" id="app"></div><script>
const D={meeting:[['會議室 3F-3','08/05（二）09:30–10:30','已預約'],['會議室 4F-1','08/01（五）14:00–15:30','已完成'],['會議室 3F-4','07/28（一）10:00–11:00','已取消']],facility:[['健身房 3F-3','08/06（三）18:00–19:00','已預約'],['健身房 4F-1','08/02（六）10:00–11:00','已完成'],['多功能教室','07/26（六）13:00–15:00','已取消']],meal:[['每日午餐餐券','使用日期 08/01（五）','未使用'],['健康餐盒','使用日期 07/30（三）','已使用'],['商務午餐餐券','使用日期 07/25（五）','已過期']],visitor:[['陳大文 等 2 人','來訪 08/04（一）10:00','待審核'],['合作夥伴來訪','來訪 08/01（五）','已核准'],['供應商會議','來訪 07/28（一）','已完成']],issue:[['3F 茶水間咖啡機故障','建立於 07/31','未處理'],['4F 投影設備異常','建立於 07/29','處理中'],['停車場照明不足','建立於 07/22','已結案']]};let page='home',kind='meeting',balance=120,filter='全部';const A=document.querySelector('#app');const toast=m=>{A.insertAdjacentHTML('beforeend','<div class="toast">✓ '+m+'</div>');setTimeout(()=>document.querySelector('.toast')?.remove(),1800)};const nav=()=>'<nav><button onclick="go(\'home\')" class="'+(page==='home'?'on':'')+'">⌂<br>首頁</button><button onclick="module(\'meeting\')">▣<br>預約</button><button onclick="placeholder(\'活動\')">☆<br>活動</button><button onclick="module(\'visitor\')">◎<br>服務</button><button onclick="placeholder(\'更多\')">☷<br>更多</button></nav>';function go(p){page=p;render()}function header(t){return '<header><button onclick="go(\'home\')">‹</button><span>'+t+'</span><button>⋯</button></header>'}function home(){A.innerHTML='<section class="hero"><b>● NexSpace</b><h1>早安，王小明</h1><p>NexSpace A 棟 · 租客員工</p></section><main><h2>常用功能</h2><div class="grid"><button onclick="module(\'meeting\')"><span>▣</span>會議室預約</button><button onclick="module(\'meal\')"><span>▤</span>餐券</button><button onclick="module(\'visitor\')"><span>♙</span>訪客登記</button></div><h2>全部功能</h2><div class="list">'+['會議室預約','公設預約','訪客登記','餐券／餐務','問題反映','合約資訊','繳費紀錄','資料列印系統','停車管理系統'].map(x=>'<button onclick="'+(x==='會議室預約'?'module(\\\'meeting\\\')':x==='公設預約'?'module(\\\'facility\\\')':x==='訪客登記'?'module(\\\'visitor\\\')':x==='餐券／餐務'?'module(\\\'meal\\\')':x==='問題反映'?'module(\\\'issue\\\')':'placeholder(\\\''+x+'\\\')')+'">'+x+'　›</button>').join('')+'</div></main>'+nav()}function module(k){kind=k;page='module';render()}function cards(){return D[kind].filter(x=>filter==='全部'||x[2]===filter).map((x,i)=>'<article class="card"><span class="pill">'+x[2]+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p><p class="muted">王小明 · 本機假資料</p><div class="actions">'+(x[2].includes('取消')||x[2].includes('完成')?'':'<button class="secondary" onclick="form(\\\'edit\\\','+i+')">編輯</button><button class="danger" onclick="confirmCancel('+i+')">取消</button>')+(kind==='meal'?'<button class="secondary" onclick="qr()">QR Code</button>':'')+'</div></article>').join('')||'<p class="muted">沒有符合篩選條件的資料。</p>'}function render(){if(page==='home')return home();if(page==='placeholder')return A.innerHTML=header(kind)+'<main class="center"><h2>'+kind+'功能準備中</h2><p class="muted">此原型保留可點擊入口。</p><button class="primary" onclick="go(\\\'home\\\')">返回首頁</button></main>'+nav();if(page==='qr')return A.innerHTML=header('餐券 QR Code')+'<main class="center"><h2>✓ 餐券建立成功</h2><p class="muted">請於取餐時出示 QR Code</p><div class="qr">▦<br>▦▦<br>▦ ▦</div><b>VX-8254-NS</b><br><button class="secondary cta" onclick="toast(\\\'已模擬下載 QR Code\\\')">下載</button><button class="primary cta" onclick="module(\\\'meal\\\')">返回我的餐券</button></main>';let title={meeting:'會議室預約',facility:'公設預約',meal:'餐券',visitor:'訪客登記',issue:'問題反映'}[kind];A.innerHTML=header(title)+'<main>'+(kind==='facility'?'<div class="balance">預約點數餘額 <b>'+balance+' 點</b><br><button onclick="topup()">使用紀錄／儲值點數</button></div>':kind==='meal'?'<div class="balance">可用餐券 <b>6 張</b></div>':'')+(kind==='meeting'||kind==='facility'?'<div class="tabs"><button class="on">我的預約</button><button onclick="search()">預約查詢</button></div>':'')+'<div class="actions"><h2 style="flex:1">'+(kind==='issue'?'問題列表':kind==='visitor'?'訪客紀錄':kind==='meal'?'我的餐券／訂單':'我的預約')+'</h2><button class="primary" onclick="form(\\\'new\\\')">'+(kind==='issue'?'問題反映':kind==='visitor'?'新增訪客':kind==='meal'?'新增餐券':'＋ 預約')+'</button></div>'+(kind==='visitor'||kind==='issue'?'<div class="filter"><button class="secondary" onclick="applyFilter()">篩選</button><button onclick="filter=\\\'全部\\\';render()">清除篩選</button></div>':'')+(kind==='meal'?'<button class="secondary cta" onclick="people()">常用取餐人管理</button>':'')+cards()+'</main>'+nav()}function search(){A.innerHTML=header('預約查詢')+'<main class="form"><label>棟別／區域<select><option>NexSpace A 棟</option></select></label><label>使用人數<input placeholder="請輸入人數"></label><label>開始日期／時間<input value="2026-08-05 10:00"></label><button class="primary cta" onclick="form(\\\'new\\\')">搜尋並選擇可用空間</button><article class="card"><h3>'+ (kind==='facility'?'健身房 4F-1 · 20 點':'會議室 3F-4 · 10 人')+'</h3><p>可預約 · 投影設備</p><button class="secondary" onclick="form(\\\'new\\\')">預約</button></article></main>'}function form(mode,i){page='form';let t=mode==='edit'?'編輯':'新增';A.innerHTML=header(t+(kind==='issue'?'問題':kind==='visitor'?'訪客':kind==='meal'?'餐券':'預約'))+'<main class="form"><label>'+ (kind==='issue'?'問題類型':kind==='visitor'?'受訪部門':kind==='meal'?'餐券方案':'使用部門')+' *<select><option>產品部</option><option>行政部</option></select></label><label>'+ (kind==='issue'?'反映內容／標題':kind==='visitor'?'訪客姓名':kind==='meal'?'取餐人姓名':'會議主旨')+' *<input id="name" placeholder="請輸入內容" value="'+(mode==='edit'?D[kind][i][0]:'')+'"></label>'+(kind==='visitor'?'<label>Email *<input placeholder="name@example.com"></label>':'')+'<label>備註／說明<textarea></textarea></label>'+(kind==='issue'?'<div class="upload">＋ 上傳現場照片（最多 4 張）</div>':'')+'<button class="primary cta" onclick="submitForm(\\\''+mode+'\\\','+(i??-1)+')">送出</button></main>'}function submitForm(mode,i){let n=document.querySelector('#name').value;if(!n)return toast('請填寫必填欄位');if(mode==='edit')D[kind][i][0]=n;else D[kind].unshift([n,'建立於 今日',kind==='issue'?'未處理':kind==='visitor'?'待審核':kind==='meal'?'未使用':'已預約']);if(kind==='meal')return qr();module(kind);toast('送出成功，列表已更新')}function confirmCancel(i){A.insertAdjacentHTML('beforeend','<div class="modal"><div><h2>確定要取消嗎？</h2><p class="muted">取消後將更新預約狀態。</p><button class="secondary" onclick="render()">返回</button><button class="danger" onclick="D[kind]['+i+'][2]=\\\'已取消\\\';render();toast(\\\'已取消，列表已更新\\\')">確定取消</button></div></div>')}function qr(){page='qr';render()}function applyFilter(){filter=filter==='全部'?(kind==='issue'?'處理中':'待審核'):'全部';render();toast('已套用篩選')}function topup(){balance+=100;module('facility');toast('儲值成功，點數已更新')}function people(){A.innerHTML=header('常用取餐人')+'<main><article class="card"><h3>王小明</h3><p>總機服務台 · 0912-345-678</p></article><article class="card"><h3>林美玲</h3><p>4F 接待區 · 0988-111-222</p></article><button class="primary cta" onclick="toast(\\\'已新增取餐人\\\')">新增取餐人</button></main>'}home();</script></body></html>`;
export default { async fetch() { return new Response(html, {headers:{"content-type":"text/html;charset=UTF-8"}}); } };
